                throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} evolved read lost '{diff}' ({Clr[Array.IndexOf(Props, diff)]}) at row {index} (mask {mask:x}); expected {DeepEq.Describe(expected[index][Array.IndexOf(Props, diff)])}.");
            index++;
        }
        if (index != expected.Length)
            throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} evolved read returned {index} of {expected.Length} rows.");
    }

    public override List<int> ReadSeqs(byte[] bytes, object[] rows, RowReaderOptions options)
    {
        var seqs = new List<int>();
        using var reader = Rnd684v.CreateRowReader(new MemoryStream(bytes, writable: false), default, options);
        while (reader.MoveNext())
        {
            var seq = reader.Current.Seq;
            if ((uint)seq >= (uint)rows.Length)
                throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} dataset file returned unknown Seq {seq}.");
            var diff = Compare(reader.Current, (Rnd684v)rows[seq], 511);
            if (diff is not null)
                throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} dataset lost '{diff}' of row {seq}.");
            seqs.Add(seq);
        }
        return seqs;
    }

    public override IRandomDatasetSink CreateDataset(Func<object, int> partitionOf, bool ownedPath, bool createParts, FaultingDatasetFile[] files, DatasetWriterOptions options)
    {
        Rnd684v.Route route = (Rnd684v row, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.Select(partitionOf(row), ownedPath, pool, out allocation);
        DatasetFilePath filePath = (ReadOnlySpan<byte> key, ulong index, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd684v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd684v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd684v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd684v)row);
        public void Dispose() => writer.Dispose();
    }
}